import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class FontService {

    constructor() { }

    private _fonts: Font[] = [
      {
        fontName: 'BoehringerForwardHead',
        ttfName: 'BoehringerForwardHead-normal.ttf',
        fontWeight: 'normal',
        base64: ''
      },
      {
        fontName: 'BoehringerForwardText',
        ttfName: 'BoehringerForwardText-normal.ttf',
        fontWeight: 'normal',
        base64: ''
      }

    ]

    get fonts() {
      return this._fonts;
  }
}

export interface Font{
  fontName: string;
  ttfName: string;
  fontWeight: string;
  base64: string;
}